script:
card({ name: "Maths race", icon: 'divide', permissions: ['sound'] });
const words = {
  start: "Start the race",
  about: "Ten sums. The first right answer scores.",
  question: "Question {p0} of {p1}",
  got: "{p0} got {p1}",
  out: "Wrong: wait for the next one",
  sitOut: "You're out for this one",
  won: "{p0} wins with {p1}",
  again: "Race again",
  notStarted: "Start the race first",
};

const ROUNDS = 10;

function init() {
  return { q: null, round: 0, score: {}, names: {}, out: [], last: null, done: false };
}

// A sum, its answer, and four answers to pick from in a fair order.
function question(ctx) {
  const pick = n => Math.floor(ctx.random() * n);
  const op = ['+', '−', '×'][pick(3)];
  let a = 2 + pick(12);
  let b = 2 + pick(12);
  if (op === '−' && b > a) {
    const t = a;
    a = b;
    b = t;
  }
  const answer = op === '+' ? a + b : op === '−' ? a - b : a * b;
  const options = [answer];
  while (options.length < 4) {
    const near = answer + (pick(2) ? 1 : -1) * (1 + pick(op === '×' ? 12 : 5));
    if (near >= 0 && !options.includes(near)) options.push(near);
  }
  for (let i = options.length - 1; i > 0; i--) {
    const j = pick(i + 1);
    const t = options[i];
    options[i] = options[j];
    options[j] = t;
  }
  return { text: a + ' ' + op + ' ' + b, answer, options };
}

on.start = (s, args, ctx) => {
  const fresh = init();
  fresh.q = question(ctx);
  fresh.round = 1;
  return fresh;
};

on.answer = (s, args, ctx) => {
  if (!s.q) throw words.notStarted;
  if (s.out.includes(ctx.author)) throw words.sitOut;
  s.names[ctx.author] = ctx.authorName;
  if (args.pick !== s.q.answer) {
    s.out.push(ctx.author);
    ctx.sound('buzz', { for: ctx.author });
    return;
  }
  s.score[ctx.author] = (s.score[ctx.author] || 0) + 1;
  s.last = { name: ctx.authorName, text: s.q.text + ' = ' + s.q.answer };
  s.out = [];
  if (s.round >= ROUNDS) {
    s.q = null;
    s.done = true;
    ctx.sound('win');
  } else {
    s.round++;
    s.q = question(ctx);
    ctx.sound('coin');
  }
};

function view(s, me) {
  const ids = Object.keys(s.score).sort((a, b) => s.score[b] - s.score[a]);
  const board = row(ids.map((id, i) => badge(s.names[id] + ' ' + s.score[id], { tone: i === 0 ? 'accent' : undefined })), { align: 'center' });
  if (!s.q) {
    return column([
      s.done && ids.length
        ? text(words.won.replace('{p0}', s.names[ids[0]]).replace('{p1}', s.score[ids[0]]), { size: 'large', bold: true, align: 'center', tone: 'success' })
        : text(words.about, { align: 'center' }),
      s.done && board,
      button(s.done ? words.again : words.start, 'start', null, { tone: 'accent', align: 'center' }),
    ]);
  }
  const out = s.out.includes(me.id);
  return column([
    text(words.question.replace('{p0}', s.round).replace('{p1}', ROUNDS), { size: 'small', tone: 'muted', align: 'center' }),
    progress(s.round / ROUNDS),
    text(s.q.text, { size: 'huge', bold: true, align: 'center' }),
    grid(4, s.q.options.map(n => button(String(n), 'answer', { pick: n }, { size: 'large', tone: out ? 'muted' : 'accent' }))),
    out && text(words.out, { tone: 'warning', align: 'center' }),
    s.last && text(words.got.replace('{p0}', s.last.name).replace('{p1}', s.last.text), { size: 'small', tone: 'muted', align: 'center' }),
    board,
  ]);
}
